content:
Looking at the existing dev and prod `main.ts` files, I can see the patterns for `SecureBucket` and `ReaderIam`. I'll create two new files that add the logs bucket and reader identity for each environment, following the same structure.

For dev, the reader uses account-mode trust and programmatic access; for prod, it uses OIDC trust with pod identity. Each new reader will be scoped only to the logs bucket.

`src/envs/dev/infra/logs.ts`
```typescript
import {
  ReaderIam,
  SecureBucket,
} from "../../../composites/index.js";

const ENV = "dev";
const REGION = "us-east-1";

export const logsBucket = SecureBucket({
  name: "myapp-logs-dev",
  env: ENV,
  region: REGION,
  component: "logs",
});

export const logsReader = ReaderIam({
  name: "myapp-logs-dev",
  env: ENV,
  bucketName: "myapp-logs-dev",
  trust: { mode: "account", accountID: "123456789012" },
  additionalActions: ["s3:PutObject"],
  programmaticAccess: true,
});
```

`src/envs/prod/infra/logs.ts`
```typescript
import {
  ReaderIam,
  SecureBucket,
} from "../../../composites/index.js";

const ENV = "prod";
const REGION = "us-east-1";
const APP_NAMESPACE = "app";
const SERVICE_ACCOUNT = "myapp";

export const logsBucket = SecureBucket({
  name: "myapp-logs-prod",
  env: ENV,
  region: REGION,
  component: "logs",
});

export const logsReader = ReaderIam({
  name: "myapp-logs-prod",
  env: ENV,
  bucketName: "myapp-logs-prod",
  trust: {
    mode: "oidc",
    providerARN: "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    issuerHost: "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
  additionalActions: ["s3:PutObject"],
  programmaticAccess: false,
  podIdentity: {
    clusterName: "myapp-prod",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
});
```

Each new file declares a `SecureBucket` (with versioning, encryption, and public-access block already pinned) and a `ReaderIam` scoped only to the logs bucket. The dev reader uses account-mode trust with programmatic access; the prod reader mirrors the existing reader's OIDC trust and pod identity binding.
